LEVEL = 1
CFG = {1: ("1.4.2", "^1.2.0"), 2: ("2.0.0", "^1.2.0"), 3: ("1.9.0", ">=1.0.0,<2.0.0")}
ver, req = CFG[LEVEL]
def parse(v): return tuple(int(x) for x in v.split("."))
def ok(v, r):
    p = parse(v)
    if r.startswith("^"): b = parse(r[1:]); return p[0] == b[0] and p >= b
    lo, hi = r.split(","); return parse(lo[2:]) <= p < parse(hi[1:])
print("version", ver, "vs", req, "->", "COMPATIBLE" if ok(ver, req) else "BLOCKED")

