LEVEL = 1
CFG = {1: {"a": ["1.0", "1.1"], "b": ["2.0"]}, 2: {"a": ["1.0", "1.1", "2.0"], "b": ["2.0", "2.1"]}, 3: {"a": ["1.0", "2.0"], "b": ["3.0"]}}
avail = CFG[LEVEL]
constraints = {"a": lambda v: v.startswith("1."), "b": lambda v: True}
resolved, conflict = {}, None
for pkg, versions in avail.items():
    pick = next((v for v in versions if constraints[pkg](v)), None)
    if pick is None: conflict = pkg; break
    resolved[pkg] = pick
print("resolved:", resolved, "| conflict:", conflict or "none")

